from google.cloud import vision


def get_vision_client():
    return vision.ImageAnnotatorClient()

def normalize_image_description(response):
    return {"description": response.dominant_colors.colors[0].description}


def normalize_text_detection(response):
    return {"text": response.text}


def normalize_safety_score(response):
    return {"adult": response.adult, "spoof": response.spoof, "medical": response.medical, "violence": response.violence}
